// Synthetic demo data only. No real patient, staff, or organization data is
// ever committed to or generated by this repository — see docs/privacy-model.md.
// All emails use the reserved `example.test` domain (RFC 2606) and all
// content is faker-generated.
import { faker } from "@faker-js/faker";
import { hashPassword } from "@clinic/shared";
import { PrismaClient, Role } from "../generated/client";
import { encryptField, encryptOptionalField } from "../src/encryption";

faker.seed(42); // reproducible demo dataset across runs

// Uses the BYPASSRLS platform role deliberately: this script is a trusted,
// operator-run local/CI tool (never reachable from application code paths),
// and every tenant table has FORCE ROW LEVEL SECURITY enabled — inserting
// through the ordinary `clinic_app` role with no tenant session context set
// would be rejected by every policy. See docs/multi-tenancy.md.
const prisma = new PrismaClient({
  datasources: { db: { url: process.env.DATABASE_URL_PLATFORM } },
});

const DEMO_PASSWORD = "Demo-Passw0rd!"; // local/demo only — never used outside seed data

async function createClinic(name: string, slug: string) {
  const clinic = await prisma.clinic.create({
    data: { name, slug, timezone: "Europe/Istanbul" },
  });

  const departments = await Promise.all(
    ["General Medicine", "Pediatrics", "Dermatology"].map((deptName) =>
      prisma.department.create({
        data: { clinicId: clinic.id, name: deptName },
      }),
    ),
  );

  const passwordHash = await hashPassword(DEMO_PASSWORD);

  async function createStaffUser(role: Role, departmentId?: string) {
    const first = faker.person.firstName();
    const last = faker.person.lastName();
    const email = `${slug}.${role.toLowerCase()}.${faker.string.alphanumeric(5).toLowerCase()}@example.test`;
    const user = await prisma.user.create({
      data: { email, passwordHash, isActive: true },
    });
    const membership = await prisma.membership.create({
      data: {
        userId: user.id,
        clinicId: clinic.id,
        role,
        departmentId,
        status: "ACTIVE",
        joinedAt: new Date(),
      },
    });
    return { user, membership, first, last };
  }

  const clinicAdmin = await createStaffUser("CLINIC_ADMIN");
  const receptionist = await createStaffUser(
    "RECEPTIONIST",
    departments[0]!.id,
  );
  const billingManager = await createStaffUser("BILLING_MANAGER");
  const nurse = await createStaffUser("NURSE", departments[0]!.id);

  const doctors = await Promise.all(
    departments.map(async (dept) => {
      const staff = await createStaffUser("DOCTOR", dept.id);
      const doctorProfile = await prisma.doctorProfile.create({
        data: {
          clinicId: clinic.id,
          membershipId: staff.membership.id,
          specialty: dept.name,
          licenseNumber: encryptField(
            `DEMO-LIC-${faker.string.alphanumeric(8).toUpperCase()}`,
          ),
          bio: `Synthetic demo profile for ${dept.name}.`,
        },
      });

      for (let day = 1; day <= 5; day += 1) {
        await prisma.availabilitySlot.create({
          data: {
            clinicId: clinic.id,
            doctorId: doctorProfile.id,
            dayOfWeek: day,
            startMinute: 9 * 60,
            endMinute: 17 * 60,
            effectiveFrom: new Date(),
          },
        });
      }

      return { ...staff, doctorProfile, department: dept };
    }),
  );

  const patients = await Promise.all(
    Array.from({ length: 6 }, async () => {
      const first = faker.person.firstName();
      const last = faker.person.lastName();
      const patient = await prisma.patientProfile.create({
        data: {
          clinicId: clinic.id,
          firstName: encryptField(first),
          lastName: encryptField(last),
          dateOfBirth: encryptField(
            faker.date
              .birthdate({ min: 1, max: 90, mode: "age" })
              .toISOString()
              .slice(0, 10),
          ),
          phone: encryptOptionalField(
            faker.phone.number({ style: "international" }),
          ),
          email: encryptOptionalField(
            `${first}.${last}.${faker.string.alphanumeric(4)}@example.test`.toLowerCase(),
          ),
          address: encryptOptionalField(
            JSON.stringify({
              line1: faker.location.streetAddress(),
              city: faker.location.city(),
              postalCode: faker.location.zipCode(),
              country: faker.location.country(),
            }),
          ),
        },
      });
      return { patient, first, last };
    }),
  );

  // A handful of appointments, one finalized medical record with a note,
  // one invoice, and a document metadata row (no actual file bytes — see
  // docs/document-security.md; storageKey points at nothing in demo data).
  for (let i = 0; i < 5; i += 1) {
    const doctor = doctors[i % doctors.length]!;
    const patientEntry = patients[i % patients.length]!;
    const startsAt = faker.date.soon({ days: 14 });
    const endsAt = new Date(startsAt.getTime() + 30 * 60 * 1000);

    const appointment = await prisma.appointment.create({
      data: {
        clinicId: clinic.id,
        patientId: patientEntry.patient.id,
        doctorId: doctor.doctorProfile.id,
        departmentId: doctor.department.id,
        startsAt,
        endsAt,
        status: "CONFIRMED",
        reason: "Routine check-up",
        createdByMembershipId: receptionist.membership.id,
      },
    });

    if (i === 0) {
      const record = await prisma.medicalRecord.create({
        data: {
          clinicId: clinic.id,
          patientId: patientEntry.patient.id,
          doctorId: doctor.doctorProfile.id,
          appointmentId: appointment.id,
          visitDate: startsAt,
          chiefComplaint: encryptField("Synthetic demo chief complaint."),
          diagnosisNotes: encryptField(
            "Synthetic demo diagnosis notes — no real clinical content.",
          ),
          status: "FINALIZED",
        },
      });

      await prisma.treatmentNote.create({
        data: {
          clinicId: clinic.id,
          medicalRecordId: record.id,
          authorMembershipId: doctor.membership.id,
          noteType: "progress",
          content: encryptField("Synthetic demo treatment note content."),
        },
      });

      await prisma.document.create({
        data: {
          clinicId: clinic.id,
          ownerPatientId: patientEntry.patient.id,
          medicalRecordId: record.id,
          uploadedByMembershipId: doctor.membership.id,
          category: "CLINICAL",
          originalFilename: "demo-lab-result.pdf",
          declaredMimeType: "application/pdf",
          detectedMimeType: "application/pdf",
          sizeBytes: 128_000,
          storageKey: `demo/${clinic.id}/${faker.string.uuid()}.pdf`,
          status: "AVAILABLE",
        },
      });
    }

    const invoice = await prisma.invoice.create({
      data: {
        clinicId: clinic.id,
        patientId: patientEntry.patient.id,
        appointmentId: appointment.id,
        status: "ISSUED",
        totalAmount: 75.0,
        issuedAt: new Date(),
        dueAt: faker.date.soon({ days: 30 }),
        lineItems: {
          create: [
            {
              description: "Consultation fee (demo)",
              quantity: 1,
              unitAmount: 75.0,
              amount: 75.0,
            },
          ],
        },
      },
    });

    if (i % 2 === 0) {
      await prisma.payment.create({
        data: {
          invoiceId: invoice.id,
          amount: 75.0,
          method: "CARD_ON_FILE_TOKEN",
          reference: "demo-ref",
        },
      });
      await prisma.invoice.update({
        where: { id: invoice.id },
        data: { status: "PAID" },
      });
    }
  }

  console.log(`Seeded clinic "${name}" (${slug})`);
  console.log(`  clinic admin:   ${clinicAdmin.user.email}`);
  console.log(`  receptionist:   ${receptionist.user.email}`);
  console.log(`  billing mgr:    ${billingManager.user.email}`);
  console.log(`  nurse:          ${nurse.user.email}`);
  doctors.forEach((d) =>
    console.log(`  doctor:         ${d.user.email} (${d.department.name})`),
  );

  return { clinic };
}

async function main() {
  const superAdminEmail = "super.admin@example.test";
  await prisma.user.create({
    data: {
      email: superAdminEmail,
      passwordHash: await hashPassword(DEMO_PASSWORD),
      isSuperAdmin: true,
      isActive: true,
    },
  });

  await createClinic("Demo Family Clinic", "demo-family-clinic");
  await createClinic("Second Demo Clinic", "second-demo-clinic");

  console.log("\nAll demo accounts share the password:", DEMO_PASSWORD);
  console.log("Super admin:", superAdminEmail);
  console.log(
    "\nThis is entirely synthetic data for local development. Do not use in production.",
  );
}

main()
  .catch((error) => {
    console.error(error);
    process.exitCode = 1;
  })
  .finally(async () => {
    await prisma.$disconnect();
  });
